def _in_fov(self, point, origin, radius=5.0, fov_angle=np.pi/2):
"""判断点是否在视野内"""
dist = np.sqrt((point[0]-origin[0])**2 + (point[1]-origin[1])**2)
if dist > radius:
return False
angle = np.arctan2(point[1]-origin[1], point[0]-origin[0])
return abs(angle) <= fov_angle/2
