def _dijkstra_shortest_path(self, start, end):
"""Dijkstra 最短路径"""
dist = {n: float('inf') for n in self.graph}
dist[start] = 0
prev = {n: None for n in self.graph}
heap = [(0, start)]
visited = set()
while heap:
d, u = heapq.heappop(heap)
if u in visited:
continue
if u == end:
break
visited.add(u)
for v, w in self.graph[u].items():
if v not in visited and d + w < dist[v]:
dist[v] = d + w
prev[v] = u
heapq.heappush(heap, (dist[v], v))
# 重建路径
path = []
curr = end
while curr is not None:
path.append(curr)
curr = prev.get(curr)
return path[::-1] if path and path[0] == start else None
